// 16×16 icon for logos rendered as icon + title.
function Icon({
  height,
  children,
}: {
  height: number
  children: React.ReactNode
}) {
  return (
    <svg
      xmlns='http://www.w3.org/2000/svg'
      viewBox='0 0 16 16'
      height={height}
      width={height}
      fill='currentColor'
      aria-hidden
    >
      {children}
    </svg>
  )
}

